export const articles={"what-is-bmi":{title:"What Is BMI?",description:"A plain-language explanation of Body Mass Index and how it is used.",body:["BMI, or Body Mass Index, compares a person’s weight with their height. It is widely used as an adult screening measure because it is quick to calculate and research links BMI ranges with health outcomes across populations.","BMI does not measure body fat directly. Two people can share a BMI and have different muscle mass, fat distribution, fitness, and health history. That is why it belongs alongside—not instead of—clinical assessment."]},"bmi-formula-explained":{title:"BMI Formula Explained",description:"The BMI calculation in metric and imperial units, with examples.",body:["The metric calculation is kilograms divided by metres squared. A person weighing 70 kilograms at 1.70 metres has a BMI of 24.2.","The imperial calculation is pounds multiplied by 703, divided by inches squared. Reliable tools convert measurements automatically, but knowing the formula can make a result easier to understand."]},"healthy-weight-guide":{title:"Healthy Weight Guide",description:"A compassionate, practical guide to healthy-weight habits.",body:["Healthy weight is not one number or one appearance. It is best considered alongside energy, strength, sleep, blood pressure, food access, medical history, and what is sustainable in real life.","Regular meals, enjoyable movement, resistance exercise, sleep, and social support create a stronger foundation than extreme dieting. A registered dietitian or clinician can personalize support."]},"bmi-vs-body-fat":{title:"BMI vs Body Fat",description:"How BMI differs from body-fat percentage and why both can have limits.",body:["BMI uses height and weight only. Body-fat percentage aims to estimate the share of weight from fat tissue. Neither measurement tells the whole health story in isolation.","Body-composition scales can vary with hydration and technique. Trends, waist measurement, and clinical markers can be more meaningful than a one-off reading."]},"ideal-weight-by-height":{title:"Ideal Weight by Height",description:"Why a healthy-weight range is more useful than a single ideal weight.",body:["A BMI calculator can translate the standard healthy BMI range into a weight range for a height. This is a mathematical reference point, not a mandate or a promise of health.","Body frame, muscle mass, age, health conditions, and personal goals all affect what a suitable weight means for an individual."]},"bmi-limitations":{title:"BMI Limitations",description:"The important limits of BMI as a health screen.",body:["BMI does not measure fat distribution, fitness, nutrition, blood pressure, or metabolic health. It may overestimate fatness in muscular people and underestimate risk in others.","Pregnancy, children, older age, disability, and ethnicity may need a more individualized interpretation. A clinician can help select additional measures."]},"lose-weight-safely":{title:"How to Lose Weight Safely",description:"Evidence-informed principles for gradual, sustainable weight management.",body:["Safe change is usually gradual and supported by nourishing meals, activity, sleep, and realistic routines. Severe restriction can increase fatigue, nutrient shortfalls, and rebound eating.","If weight loss is a goal, a clinician or registered dietitian can consider medications, health conditions, and an approach that protects muscle and wellbeing."]}} as const;
