import { notFound } from "next/navigation"; import { articles } from "@/lib/articles"; import { ArticlePage } from "@/components/article-page"; import { Definition } from "@/components/ui"; type Props={params:Promise<{slug:string}>}; export function generateStaticParams(){return Object.keys(articles).map(slug=>({slug}))} export async function generateMetadata({params}:Props){const {slug}=await params;const a=articles[slug as keyof typeof articles];return a?{title:a.title,description:a.description}:{title:"Article not found"}} export default async function Page({params}:Props){const {slug}=await params;const a=articles[slug as keyof typeof articles];if(!a)notFound();return <ArticlePage path={`/blog/${slug}`} title={a.title} description={a.description}><Definition><strong>Quick answer:</strong> {a.description}</Definition>{a.body.map((p,i)=><p key={i}>{p}</p>)}<h2>Use this information carefully</h2><p>Health advice works best when adapted to your own situation. A BMI result can be a useful opening measure, but it should never replace individualized medical care.</p></ArticlePage>}
